sql.where:
p.status <> 'HIDDEN'



		AND p.barcode = #{barcode}


		AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR a.name LIKE CONCAT('%', #{keyword}, '%')

			OR p.catalog_no_normalized = #{catalogNoNormalized}

		)



	AND p.artist_id = #{artistId}


	AND p.label_id = #{labelId}


	AND p.album_id = #{albumId}


	AND p.country = #{country}


	AND p.pressing_year >= #{pressingYearFrom}


	AND p.pressing_year <= #{pressingYearTo}


	AND p.edition_type = #{editionType}


	AND EXISTS (
		SELECT 1 FROM product_genre pg
		WHERE pg.product_id = p.id
		AND pg.genre_id IN
		#{genreId}
	)


	AND p.price >= #{minPrice}


	AND p.price <= #{maxPrice}

mapper.select:
SELECT t.id, t.title, t.artist_name, t.label_name, t.price, t.color_variant, t.pressing_info, t.status, (SELECT MIN(i.image_url) FROM product_image i WHERE i.product_id = t.id AND i.sort_order = 0) AS thumbnail_url, t.average_rating, t.review_count,
EXISTS (SELECT 1 FROM wishlist w WHERE w.product_id = t.id AND w.member_id = #{memberId})
NULL AS wishlisted, t.country, t.pressing_year, t.edition_type, t.album_id, t.album_match_count - 1 AS other_pressing_count FROM ( SELECT , ROW_NUMBER() OVER ( PARTITION BY ORDER BY (p.status = 'SOLD_OUT'), ) AS rn, COUNT(*) OVER (PARTITION BY ) AS album_match_count
) t WHERE t.rn = 1 ORDER BY LIMIT #{size} OFFSET #{offset}
